preConditionHook:
// Two independent WFSafe_AvgTrueRange call sites, one per length. Each is
// MultiWalk's ROLLING accumulator (see AtrProfitTarget): seeded with a full sum
// on the first calculated bar or when its length changes, then updated as TWO
// statements S += in; S -= out; -- EL evaluates S[1] + in - out left to right
// and folding it rounds differently.
if (fastLength != (int)fastLookback) {
    fastSum = 0.0;
    for (int i = 0; i < (int)fastLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        fastSum += hi - lo;
    }
    fastLength = (int)fastLookback;
} else {
    const int out = (int)fastLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    fastSum += hiIn - loIn;
    fastSum -= hiOut - loOut;
}
fastAtr = fastSum / (int)fastLookback;
if (slowLength != (int)slowLookback) {
    slowSum = 0.0;
    for (int i = 0; i < (int)slowLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        slowSum += hi - lo;
    }
    slowLength = (int)slowLookback;
} else {
    const int out = (int)slowLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    slowSum += hiIn - loIn;
    slowSum -= hiOut - loOut;
}
slowAtr = slowSum / (int)slowLookback;
